import * as M from './model.js';
import { DATA } from './data.js';
import { btn, image, line, pill, empty, tabs, chips, search, grade, number, esc } from './helpers.js';

const CARD_TABS = [['cards', '카드'], ['fusion', '합성'], ['collection', '컬렉션']];
const COLLECTION_TABS = [['equipment', '장비'], ['transform', '변신'], ['doll', '마법인형'], ['relic', '성물']];
const COLLECTION_FILTERS = ['전체', '미완성', '완성', '즐겨찾기'];
const applyLabel = { transform: '변신하기', doll: '소환하기', relic: '장착하기' };
const activeLabel = { transform: '변신 중', doll: '소환 중', relic: '장착 중' };
const signed = (value, unit = '') => `${Number(value) >= 0 ? '+' : ''}${number(value)}${esc(unit)}`;
const query = value => String(value || '').trim().toLocaleLowerCase('ko-KR');
const matches = (text, value) => query(text).includes(query(value));

function renderCardTile(s,c,card,selected,action='select-card'){
 return `<button class="collect-card ${selected?'selected':''} ${!card.owned?'unowned':''}" data-action="${action}" data-id="${card.id}" aria-label="${card.name}, ${card.grade}, ${card.owned?'보유':'미보유'}${card.locked?', 잠금':''}" aria-pressed="${selected}" style="--grade:${grade(card.grade)}">${image(card.art,card.name)}<span class="card-name">${card.name}</span>${card.spares?`<b class="card-count">${card.spares}</b>`:''}${card.locked?'<span class="card-lock">▣</span>':''}${c.equipped_id===card.id?'<span class="card-equipped">적용 중</span>':''}${!card.owned?'<span class="not-owned">미보유</span>':''}</button>`;
}
function renderCardList(s,c){
 const filtered=c.cards.filter(card=>(s.grade==='전체'||card.grade===s.grade)&&(s.ownedFilter==='전체'||(s.ownedFilter==='보유'?card.owned:!card.owned))&&matches(card.name,s.cardSearch)).sort((a,b)=>['신화','전설','영웅','희귀','고급','일반'].indexOf(a.grade)-['신화','전설','영웅','희귀','고급','일반'].indexOf(b.grade));
 const selected=filtered.find(x=>x.id===c.selected_id)||filtered[0];
 const rail=['전체','신화','전설','영웅','희귀','고급','일반'].map(g=>`<button class="grade-filter ${s.grade===g?'active':''}" data-action="grade" data-id="${g}" style="--grade:${grade(g)}"><span>${g}</span><small>(${c.cards.filter(x=>(g==='전체'||x.grade===g)&&x.owned).length}/${c.cards.filter(x=>g==='전체'||x.grade===g).length})</small></button>`).join('');
 const detail=selected?`<section class="card-detail" style="--grade:${grade(selected.grade)}"><h2>${selected.name}<small>${selected.grade}　${selected.owned?'보유':'미보유'}</small></h2><div class="card-detail-main"><div class="card-preview">${image(selected.art,selected.name)}<small>${c.equipped_id===selected.id?activeLabel[c.id]:selected.locked?'잠긴 카드':''}</small>${btn(c.equipped_id===selected.id?activeLabel[c.id]:applyLabel[c.id],'apply-card',{id:selected.id,class:'blue',disabled:!selected.owned||c.equipped_id===selected.id})}</div><div class="card-options"><h3>${c.id==='doll'?'소환 효과':c.id==='relic'?'성물 효과':'옵션 정보'}</h3>${selected.options_demo.map(o=>line(o.label,signed(o.value,o.unit))).join('')}${line('중복 카드',selected.spares+'장')}${line('잠금 상태',selected.locked?'잠금':'해제')}</div></div><footer>${btn('관련 컬렉션 ('+c.collections.filter(x=>x.requires.includes(selected.id)).length+')','related-collection',{id:selected.id})}${btn('합성','card-tab',{id:'fusion'})}</footer></section>`:empty('표시할 카드가 없습니다');
 return `<div class="card-view card-${c.id}"><aside class="grade-rail">${rail}</aside><section class="card-catalog"><div class="card-grid">${filtered.map(x=>renderCardTile(s,c,x,x.id===selected?.id)).join('')}${Array.from({length:Math.max(0,12-filtered.length)},()=>'<div class="card-empty"></div>').join('')}</div><div class="catalog-search">${chips(['전체','보유','미보유'],s.ownedFilter,'owned-filter')}${search('cardSearch',s.cardSearch,'이름 검색')}<small>보유 ${c.cards.filter(x=>x.owned).length} / ${c.cards.length}</small></div></section>${detail}</div>`;
}
function renderFusion(s,c){
 const picked=s.fusion,materials=c.cards.filter(x=>x.grade==='희귀');
 return `<div class="fusion-layout"><section class="fusion-stage"><h3>${c.label} 합성</h3><p>합성할 중복 카드 4장을 등록해 주세요.</p><div class="fusion-slots">${Array.from({length:4},(_,i)=>{const card=c.cards.find(x=>x.id===picked[i]);return card?`<button class="fusion-slot" data-action="remove-fusion" data-id="${i}">${image(card.art,card.name)}</button>`:'<div class="fusion-slot blank">＋</div>';}).join('')}</div><div class="fusion-count">${picked.length} / 4</div><div class="row">${btn('자동 등록','auto-fusion')}${btn('합성','confirm-fusion',{class:'primary',disabled:picked.length!==4})}</div><small class="hint">시연 결과 · 실제 확률을 적용하지 않습니다.</small></section><section class="fusion-materials"><h3>합성 재료 · 희귀</h3><div class="material-grid">${materials.map(x=>renderCardTile(s,c,x,picked.includes(x.id),'add-fusion')).join('')}</div><p class="hint">첫 보유 카드와 잠긴 카드는 소모하지 않습니다.</p>${picked.map(id=>`<span class="pill">${M.cardById(s,id).name}</span>`).join('')}</section></div>`;
}
export function renderCards(s){
 const c=M.category(s);if(!c)return '';
 return `<div class="cards-container">${tabs(CARD_TABS,s.cardTab,'card-tab')}${s.cardTab==='fusion'?renderFusion(s,c):s.cardTab==='collection'?renderCardCollections(s,c):renderCardList(s,c)}</div>`;
}
function filterCollection(s,col,complete,text){return matches(col.name+' '+text,s.collectionSearch)&&(s.collectionFilter==='전체'||s.collectionFilter==='미완성'&&!complete||s.collectionFilter==='완성'&&complete||s.collectionFilter==='즐겨찾기'&&col.favorite);}
function collectionRail(s){return `<aside class="collection-rail">${COLLECTION_FILTERS.map(n=>`<button class="grade-filter ${s.collectionFilter===n?'active':''}" data-action="collection-filter" data-id="${n}">${n}</button>`).join('')}</aside>`;}
function collectionHeader(s,col,current,total,effect){return `<header class="collection-entry-heading"><button class="collection-favorite ${col.favorite?'active':''}" data-action="favorite-collection" data-id="${col.id}" aria-label="${col.name} 즐겨찾기" aria-pressed="${!!col.favorite}">★</button><button class="collection-title" data-action="select-collection" data-id="${col.id}">${col.name}<small>${current} / ${total}</small></button><span>${effect}</span></header>`;}
export function renderCardCollections(s,c){
 const cols=c.collections.filter(col=>filterCollection(s,col,M.cardCollectionComplete(s,col),col.effect_demo.name)),selected=cols.find(x=>x.id===s.selectedCollection)||cols[0],complete=c.collections.filter(x=>M.cardCollectionComplete(s,x));
 return `<div class="collection-content"><div class="collection-search">${search('collectionSearch',s.collectionSearch,'컬렉션 이름 · 효과 검색')}</div><div class="collection-shell">${collectionRail(s)}<section class="collection-scroll">${cols.map(col=>{const current=col.requires.filter(id=>M.cardById(s,id)?.owned).length;return `<article class="collection-entry ${col.id===selected?.id?'selected':''}">${collectionHeader(s,col,current,col.requires.length,col.effect_demo.name+' +'+col.effect_demo.value)}<div class="collection-requirements">${col.requires.map(id=>{const card=M.cardById(s,id);return `<button class="collection-card ${card.owned?'complete':''}" data-action="open-card" data-id="${id}">${image(card.art,card.name)}<span>${card.name}</span><small>${card.owned?'보유':'미보유'}</small></button>`;}).join('')}</div></article>`;}).join('')||empty('검색 결과가 없습니다')}</section><aside class="collection-side"><h3>컬렉션 효과</h3>${line('완성',complete.length+' / '+c.collections.length)}${complete.map(x=>line(x.effect_demo.name,'+'+x.effect_demo.value)).join('')||'<p class="hint">완성한 컬렉션이 없습니다.</p>'}<div class="divider"></div>${selected?`<h3>${selected.name}</h3>${line('효과',selected.effect_demo.name+' +'+selected.effect_demo.value)}<p class="notice">필요한 카드를 모두 보유하면 자동 적용됩니다.</p><small class="hint">카드는 소모하지 않습니다.</small>`:''}</aside></div></div>`;
}
function equipmentComplete(c){return c.requirements.every(r=>c.registered.includes(r.slot));}
function requirementArt(s,r){return s.items.find(x=>M.normalizeName(x.name)===M.normalizeName(r.name))?.art||DATA.items.find(x=>M.normalizeName(x.name)===M.normalizeName(r.name))?.art||'';}
function renderEquipmentCollections(s){
 const cols=s.equipmentCollections.filter(col=>filterCollection(s,col,equipmentComplete(col),col.demo_effect)),selected=cols.find(x=>x.id===s.selectedCollection)||cols[0],req=selected?.requirements.find(x=>x.slot===s.selectedRequirement)||selected?.requirements[0],eligible=req?M.eligibleItems(s,req):[],registered=selected&&req&&selected.registered.includes(req.slot);
 return `<div class="collection-content"><div class="collection-search">${search('collectionSearch',s.collectionSearch,'컬렉션 이름 · 효과 검색')}</div><div class="collection-shell">${collectionRail(s)}<section class="collection-scroll">${cols.map(col=>`<article class="collection-entry ${col.id===selected?.id?'selected':''}">${collectionHeader(s,col,col.registered.length,col.requirements.length,col.demo_effect)}<div class="collection-requirements equipment-requirements">${col.requirements.map(r=>`<button class="requirement-slot ${col.registered.includes(r.slot)?'registered':''} ${selected?.id===col.id&&req?.slot===r.slot?'selected':''}" data-action="select-requirement" data-id="${r.slot}" data-collection="${col.id}" aria-label="+${r.enchant} ${r.name}, ${r.count}개 필요">${image(requirementArt(s,r),r.name)}<b>+${r.enchant}</b><span>${r.name}</span><small>${col.registered.includes(r.slot)?'등록 완료':r.count+'개 필요'}</small></button>`).join('')}</div></article>`).join('')||empty('검색 결과가 없습니다')}</section><aside class="collection-side"><h3>아이템 정보</h3>${req?`<div class="collection-item-preview">${image(requirementArt(s,req),req.name)}<strong>+${req.enchant} ${req.name}</strong></div>${line('필요 수량',req.count+'개')}${line('등록 가능한 실물',eligible.length+'개')}${line('등록 상태',registered?'등록 완료':'미등록')}<p class="notice">등록 시 선택한 실물 아이템이 소모됩니다.</p><p class="hint">장착 중이거나 잠긴 장비는 재료에서 제외합니다. 각인 표기는 같은 이름으로 판정합니다.</p>${btn(registered?'등록 완료':eligible.length?'등록할 장비 선택':'등록 가능한 장비 없음','collection-candidates',{id:req.slot,class:'primary',disabled:registered||!eligible.length,extra:'data-collection="'+selected.id+'"'})}`:''}</aside></div></div>`;
}
export function renderCollection(s){return `<div class="all-collections">${tabs(COLLECTION_TABS,s.collectionType,'collection-type')}${s.collectionType==='equipment'?renderEquipmentCollections(s):renderCardCollections(s,M.category(s,s.collectionType))}</div>`;}
